<?php require_admin();$tab=(string)($_GET['tab']??'overview');$tabs=['overview','products','orders','messages'];if(!in_array($tab,$tabs,true))$tab='overview';$metrics=['products'=>(int)db()->query('SELECT COUNT(*) FROM products WHERE active=1')->fetchColumn(),'orders'=>(int)db()->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'pending'=>(int)db()->query("SELECT COUNT(*) FROM orders WHERE status='pending'")->fetchColumn(),'revenue'=>(float)db()->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status='completed'")->fetchColumn()]; ?>
<section class="page-heading compact dashboard-heading"><div class="container"><span class="eyebrow">BAKERY MANAGEMENT</span><h1>Your business, <em>beautifully organized.</em></h1><p>Welcome, <?=h(auth()['name'])?>. Manage the moments that matter.</p></div></section><section class="container section admin-layout"><aside class="admin-nav"><a class="<?=$tab==='overview'?'current':''?>" href="<?=h(url('admin'))?>">◫ &nbsp; Overview</a><a class="<?=$tab==='products'?'current':''?>" href="<?=h(url('admin',['tab'=>'products']))?>">▦ &nbsp; Products</a><a class="<?=$tab==='orders'?'current':''?>" href="<?=h(url('admin',['tab'=>'orders']))?>">☷ &nbsp; Orders</a><a class="<?=$tab==='messages'?'current':''?>" href="<?=h(url('admin',['tab'=>'messages']))?>">✉ &nbsp; Messages</a><a href="<?=h(url())?>">↗ &nbsp; Visit store</a></aside><div class="admin-main"><?php if($tab==='overview'):?><div class="stats-grid"><div class="stat"><span>Active products</span><strong><?=$metrics['products']?></strong><small>Available to shop</small></div><div class="stat"><span>Total orders</span><strong><?=$metrics['orders']?></strong><small>All-time placed</small></div><div class="stat"><span>New orders</span><strong><?=$metrics['pending']?></strong><small>Awaiting action</small></div><div class="stat"><span>Completed revenue</span><strong><?=h(money($metrics['revenue']))?></strong><small>Finished orders only</small></div></div><div class="admin-panel"><h2>Welcome to your dashboard ✳</h2><p>Use the sidebar to manage products, monitor incoming orders and read messages from your customers.</p><a class="btn btn-secondary" href="<?=h(url('admin',['tab'=>'orders']))?>">View orders ↗</a></div>
<?php elseif($tab==='products'):$editId=(int)($_GET['edit']??0);$editing=null;if($editId){$e=db()->prepare('SELECT * FROM products WHERE id=? AND active=1');$e->execute([$editId]);$editing=$e->fetch()?:null;}$cats=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();$all=db()->query('SELECT p.*,c.name AS category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.active=1 ORDER BY p.id DESC')->fetchAll();?><div class="admin-panel"><h2><?=$editing?'Edit product':'Add a product'?></h2><form method="post" action="<?=h(url('admin',['tab'=>'products']))?>" class="admin-product-form"><?=csrf_input()?><input type="hidden" name="action" value="admin_product_save"><input type="hidden" name="id" value="<?=intval($editing['id']??0)?>"><div class="field"><label>Name</label><input name="name" maxlength="120" required value="<?=h($editing['name']??'')?>"></div><div class="field"><label>Category</label><select name="category_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($editing['category_id']??0)==$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Price (JOD)</label><input type="number" name="price" step="0.01" min="0.01" required value="<?=h((string)($editing['price']??''))?>"></div><div class="field"><label>Stock</label><input type="number" name="stock" min="0" required value="<?=h((string)($editing['stock']??0))?>"></div><div class="field"><label>Short tagline</label><input name="short_description" maxlength="200" value="<?=h($editing['short_description']??'')?>"></div><div class="field"><label>Photo theme</label><select name="image_key"><?php foreach(['cake','croissant','cookies','bread','cupcake','brownie','coffee','baklava'] as $key):?><option value="<?=$key?>" <?=($editing['image_key']??'')===$key?'selected':''?>><?=ucfirst($key)?></option><?php endforeach;?></select></div><div class="field wide"><label>Description</label><textarea name="description" maxlength="2000"><?=h($editing['description']??'')?></textarea></div><label class="checkbox-row"><input type="checkbox" name="featured" <?=!empty($editing['featured'])?'checked':''?>> Featured product</label><div class="wide"><button class="btn btn-primary" type="submit">Save product ↗</button><?php if($editing):?><a href="<?=h(url('admin',['tab'=>'products']))?>" class="small-btn">Cancel edit</a><?php endif;?></div></form></div><div class="admin-panel"><h2>Active products (<?=count($all)?>)</h2><div class="table-scroll"><table class="admin-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody><?php foreach($all as $a):?><tr><td><b><?=h($a['name'])?></b></td><td><?=h($a['category'])?></td><td><?=h(money($a['price']))?></td><td><?=intval($a['stock'])?></td><td class="actions-cell"><a class="small-btn" href="<?=h(url('admin',['tab'=>'products','edit'=>$a['id']]))?>">Edit</a><form method="post" class="inline" data-confirm="Remove this product from the store?"><?=csrf_input()?><input type="hidden" name="action" value="admin_product_delete"><input type="hidden" name="id" value="<?=intval($a['id'])?>"><button class="small-btn remove" type="submit">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
<?php elseif($tab==='orders'):$all=db()->query('SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC')->fetchAll();?><div class="admin-panel"><h2>Customer orders</h2><div class="table-scroll"><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($all as $o):?><tr><td><b>#<?=intval($o['id'])?></b><small><?=h($o['created_at'])?></small></td><td><?=h($o['customer_name'])?><small><?=h($o['phone'])?> · <?=h($o['address'])?></small></td><td><?=h(money($o['total']))?></td><td><span class="status <?=h($o['status'])?>"><?=h(ucfirst($o['status']))?></span></td><td><form method="post" class="status-form"><?=csrf_input()?><input type="hidden" name="action" value="admin_order_status"><input type="hidden" name="id" value="<?=intval($o['id'])?>"><select name="status"><?php foreach(['pending','preparing','ready','completed','cancelled'] as $s):?><option value="<?=$s?>" <?=$s===$o['status']?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select><button type="submit" class="small-btn">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php if(!$all):?><p>No orders placed yet.</p><?php endif;?></div>
<?php else:$messages=db()->query('SELECT * FROM contact_messages ORDER BY id DESC')->fetchAll();?><div class="admin-panel"><h2>Customer messages</h2><?php foreach($messages as $m):?><article class="message-card"><div><strong><?=h($m['name'])?></strong> <span>· <?=h($m['email'])?></span></div><p><?=nl2br(h($m['message']))?></p><small><?=h($m['created_at'])?></small></article><?php endforeach;?><?php if(!$messages):?><p>No messages yet.</p><?php endif;?></div><?php endif;?></div></section>
